const { withAppBuildGradle } = require('expo/config-plugins');

// Google Play takes only bundles signed with the app's own upload key; the
// prebuild template signs release with the debug keystore. android/ is
// regenerated by prebuild, so the release signing lives here. The key and its
// passwords never enter the repository: they are Gradle properties (put them
// in ~/.gradle/gradle.properties). Without them release keeps the debug key,
// so the tester APK still builds on any machine — root
// docs/decisions/android-release-config.md "업로드 키".
const STORE_FILE = 'SNAPLY_UPLOAD_STORE_FILE';

const RELEASE_SIGNING_CONFIG = `        release {
            if (findProperty('${STORE_FILE}')) {
                storeFile file(findProperty('${STORE_FILE}'))
                storePassword findProperty('SNAPLY_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('SNAPLY_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('SNAPLY_UPLOAD_KEY_PASSWORD')
            }
        }
`;

// The template's release build type, which signs with the debug keystore.
const TEMPLATE_RELEASE_SIGNING =
  /(\n\s*\/\/ Caution! In production, you need to generate your own keystore file\.\n\s*\/\/ see https:\/\/reactnative\.dev\/docs\/signed-apk-android\.\n(\s*))signingConfig signingConfigs\.debug\n/;
const DEBUG_SIGNING_CONFIG_END = /(signingConfigs \{\n\s*debug \{\n[^}]*\}\n)/;

function withReleaseSigning(contents) {
  if (contents.includes(STORE_FILE)) return contents;
  if (!TEMPLATE_RELEASE_SIGNING.test(contents) || !DEBUG_SIGNING_CONFIG_END.test(contents)) {
    // Failing prebuild beats a release that silently keeps the debug key.
    throw new Error(
      'with-release-signing: app/build.gradle no longer matches the template it rewrites',
    );
  }
  return contents
    .replace(DEBUG_SIGNING_CONFIG_END, `$1${RELEASE_SIGNING_CONFIG}`)
    .replace(
      TEMPLATE_RELEASE_SIGNING,
      `$1signingConfig findProperty('${STORE_FILE}') ? signingConfigs.release : signingConfigs.debug\n`,
    );
}

module.exports = function withReleaseSigningPlugin(config) {
  return withAppBuildGradle(config, (config) => {
    config.modResults.contents = withReleaseSigning(config.modResults.contents);
    return config;
  });
};
